<?php
namespace App\Http\Controllers;
use App\Models\{Student,StudentAttendance,StudentDiscipline,PbdAssessment};
use Illuminate\Validation\Rule;
use Illuminate\Http\Request;
class StudentAffairsController extends Controller {
    public function index(Request $request) { $school=$request->attributes->get('school'); return view('school-admin.student-affairs',['school'=>$school,'students'=>Student::latest()->get(),'attendance'=>StudentAttendance::latest()->limit(20)->get(),'discipline'=>StudentDiscipline::latest()->limit(20)->get(),'pbd'=>PbdAssessment::latest()->limit(20)->get()]); }
    public function student(Request $request) { $school=$request->attributes->get('school'); $data=$request->validate(['student_no'=>['required','string','max:80',Rule::unique('students','student_no')->where(fn ($query) => $query->where('school_id',$school->id))],'name'=>'required|string|max:160','school_class_id'=>['nullable','integer',Rule::exists('school_classes','id')->where(fn ($query) => $query->where('school_id',$school->id))]]); Student::create([...$data,'school_id'=>$school->id]); return back()->with('status','Student saved.'); }
    public function attendance(Request $request) { $school=$request->attributes->get('school'); $data=$request->validate(['student_id'=>'required|integer','attendance_date'=>'required|date','status'=>'required|in:present,absent,late,excused','reason'=>'nullable|string|max:255']); $student=Student::whereKey($data['student_id'])->where('school_id',$school->id)->firstOrFail(); StudentAttendance::updateOrCreate(['school_id'=>$school->id,'student_id'=>$student->id,'attendance_date'=>$data['attendance_date']], [...$data,'school_id'=>$school->id,'recorded_by'=>$request->user()->id]); return back()->with('status','Attendance recorded.'); }
    public function discipline(Request $request) { $school=$request->attributes->get('school'); $data=$request->validate(['student_id'=>'required|integer','incident_date'=>'required|date','category'=>'required|string|max:80','description'=>'required|string|max:5000','action_taken'=>'nullable|string|max:255']); $student=Student::whereKey($data['student_id'])->where('school_id',$school->id)->firstOrFail(); StudentDiscipline::create([...$data,'school_id'=>$school->id,'recorded_by'=>$request->user()->id]); return back()->with('status','Discipline record saved.'); }
    public function pbd(Request $request) { $school=$request->attributes->get('school'); $data=$request->validate(['student_id'=>'required|integer','subject'=>'required|string|max:120','standard'=>'nullable|string|max:120','band'=>'required|integer|min:1|max:6','evidence'=>'nullable|string|max:5000','assessed_on'=>'required|date']); $student=Student::whereKey($data['student_id'])->where('school_id',$school->id)->firstOrFail(); PbdAssessment::create([...$data,'school_id'=>$school->id,'assessed_by'=>$request->user()->id]); return back()->with('status','PBD assessment saved.'); }
}
